// ============================================================
//  SIMULATION DES NŒUDS (ESP32) — LOOZ
//  1 nœud = 1 zone du verger ; chaque nœud couvre plusieurs arbres.
//  Zones A à D : les mêmes noms que dans Supabase et le dashboard admin LOOZ.
//  Un message par NŒUD à chaque déclenchement. Paramètres ci-dessous.
// ============================================================
const ORCHARD      = "VERGER-NORD";
const TICK_MINUTES = 15;                            // minutes simulées par déclenchement (1 jour ≈ 96 ticks)
const START        = Date.UTC(2026, 5, 15, 5, 0);   // 15 juin 2026, 05:00 — heure simulée
const FIELD_CAP    = 38;                            // % humidité du sol à la capacité au champ
const WILTING      = 15;                            // % point de flétrissement
const NODES = [
    // 1 nœud ESP32 par zone. trees = arbres couverts par ce nœud.
    // scénarios : normal | irrigation_defaillante | zone_chaude | sonde_sol_defaillante
    { id: "NODE-01", zone: "A", cultivar: "Nonpareil", age: 8,  scenario: "normal",                 far: false,
      trees: ["TREE-012", "TREE-013", "TREE-014", "TREE-027", "TREE-028"] },
    { id: "NODE-02", zone: "B", cultivar: "Nonpareil", age: 10, scenario: "irrigation_defaillante", far: false,
      trees: ["TREE-042", "TREE-043", "TREE-044", "TREE-058"] },
    { id: "NODE-03", zone: "C", cultivar: "Tuono",     age: 12, scenario: "zone_chaude",            far: true,
      trees: ["TREE-073", "TREE-074", "TREE-075", "TREE-076", "TREE-077"] },
    { id: "NODE-04", zone: "D", cultivar: "Ferraduel", age: 4,  scenario: "sonde_sol_defaillante",  far: true,
      trees: ["TREE-089", "TREE-090", "TREE-091", "TREE-092"] }
];

if (flow.get("simulation_active") === false) {
    node.status({ fill: "grey", shape: "ring", text: "simulation en pause" });
    return null;
}

// ---------- horloge simulée ----------
let clock = context.get("clock");
clock = (clock === undefined) ? START : clock + TICK_MINUTES * 60000;
context.set("clock", clock);
const d   = new Date(clock);
const h   = d.getUTCHours() + d.getUTCMinutes() / 60;          // heure décimale
const day = Math.floor((clock - START) / 86400000);            // jour simulé (0 = premier jour)
const ts  = d.toISOString();
const p2  = v => String(v).padStart(2, "0");
const label = `${p2(d.getUTCDate())}/${p2(d.getUTCMonth() + 1)}/${d.getUTCFullYear()} ${p2(d.getUTCHours())}:${p2(d.getUTCMinutes())} (jour ${day + 1})`;

// ---------- météo du verger (commune) ----------
const rnd = a => (Math.random() - 0.5) * 2 * a;
const r1  = v => Math.round(v * 10) / 10;
const canicule = (day >= 1 && day <= 2) ? 3 : 0;                      // vague de chaleur jours 2-3 (+3 °C)
let cloud = context.get("cloud_" + day);
if (cloud === undefined) { cloud = 0.75 + Math.random() * 0.25; context.set("cloud_" + day, cloud); }
const tAir0 = 27 + canicule + 8 * Math.cos(2 * Math.PI * (h - 15) / 24); // min ≈ 19 °C à 03:00, max ≈ 35 °C à 15:00
const par0  = (h > 6 && h < 20) ? 1900 * cloud * Math.sin(Math.PI * (h - 6) / 14) : 0;

// ---------- somme de contrôle (recalculée par la passerelle) ----------
function checksum(p) {
    const s = [p.nodeId, p.seq, p.soil_moisture_pct, p.soil_temp_c, p.air_temp_c, p.humidity_pct, p.light_par].join("|");
    let c = 0; for (const ch of s) c = (c * 31 + ch.charCodeAt(0)) & 0xffff; return c;
}

const state    = context.get("state") || {};
const irrigate = flow.get("irrigation_urgence") || null;              // bouton du dashboard
const out = [];

NODES.forEach((t, i) => {
    const s = state[t.id] || {
        sm: (t.scenario === "irrigation_defaillante" ? 24 : FIELD_CAP - 2) + rnd(1.5),
        tsol: 22, batt: 92 + rnd(5), seq: 0, stuck: 0, stuckValue: 0
    };
    const zoneOffset = t.scenario === "zone_chaude" ? 4 : (t.far ? 1.5 : 0);
    const tAir = tAir0 + zoneOffset + rnd(0.4);
    const rh   = Math.min(95, Math.max(20, 95 - 1.9 * (tAir - 15) + rnd(2)));
    const par  = Math.max(0, par0 * (1 + rnd(0.05)));
    const es   = 0.6108 * Math.exp(17.27 * tAir / (tAir + 237.3));
    const vpd  = es * (1 - rh / 100);                                   // déficit de pression de vapeur (kPa)

    // assèchement du sol (évapotranspiration) — ≈ 7 % par jour sans irrigation
    const drying = 0.025 + 0.04 * Math.min(1, vpd / 3) + 0.02 * (par / 1900);
    s.sm = Math.max(WILTING - 6, s.sm - drying * (TICK_MINUTES / 10));
    // irrigation quotidienne à 06:00
    if (h >= 6 && h < 6 + TICK_MINUTES / 60) {
        const efficace = t.scenario !== "irrigation_defaillante";
        s.sm = efficace ? FIELD_CAP + rnd(1) : s.sm + 0.8;              // ligne fuyarde : apport dérisoire
    }
    if (irrigate === t.id) s.sm = FIELD_CAP;                           // irrigation d'urgence de la zone (agriculteur)
    s.tsol = s.tsol + 0.08 * (tAir - 2 - s.tsol);                       // sol : inertie thermique
    s.batt = Math.min(100, Math.max(5, s.batt + (par > 600 ? 0.02 : -0.015))); // recharge solaire
    s.seq += 1;

    let smRead = r1(s.sm + rnd(0.25));                                 // bruit de lecture de la sonde
    if (t.scenario === "sonde_sol_defaillante") {                       // valeurs impossibles ou figées
        if (s.stuck > 0) { smRead = s.stuckValue; s.stuck--; }
        else if (Math.random() < 0.03) smRead = [-1, 0, 101][Math.floor(Math.random() * 3)];
        else if (Math.random() < 0.012) { s.stuck = 12; s.stuckValue = smRead; }
    }
    state[t.id] = s;

    const payload = {
        nodeId: t.id, orchardId: ORCHARD, zone: t.zone, cultivar: t.cultivar, age_years: t.age,
        trees: t.trees, tree_count: t.trees.length,
        firmware: "1.2.0", seq: s.seq, timestamp: ts,
        soil_moisture_pct: smRead,
        soil_temp_c:  r1(s.tsol),
        air_temp_c:   r1(tAir),
        humidity_pct: r1(rh),
        light_par:    Math.round(par),                                  // µmol/m²/s
        vpd_kpa:      Math.round(vpd * 100) / 100,
        battery_pct:  r1(s.batt),
        rssi_dbm:     Math.round(-78 - (t.far ? 12 : 0) + rnd(6)),
        piezo_rms:    Math.round((0.02 + Math.random() * 0.01) * 1000) / 1000   // canal expérimental
    };
    payload.checksum = checksum(payload);
    out.push({ topic: `farm/${ORCHARD}/${t.id}/telemetry`, payload, lastOfTick: i === NODES.length - 1, simTime: label });
});

if (irrigate) flow.set("irrigation_urgence", null);
context.set("state", state);
node.status({ fill: "green", shape: "dot", text: label });
return [out];

// ============================================================
//  PASSERELLE DE VERGER : validation des paquets, santé des capteurs
//  (drapeaux « santé » séparés des scores biologiques — cf. §18)
// ============================================================
const GATEWAY = "GW-01";
const LIMITS = {
    soil_moisture_pct: [3, 95], soil_temp_c: [-10, 60], air_temp_c: [-15, 55],
    humidity_pct: [0, 100], light_par: [0, 2500], battery_pct: [0, 100]
};
function checksum(p) {
    const s = [p.nodeId, p.seq, p.soil_moisture_pct, p.soil_temp_c, p.air_temp_c, p.humidity_pct, p.light_par].join("|");
    let c = 0; for (const ch of s) c = (c * 31 + ch.charCodeAt(0)) & 0xffff; return c;
}

const p = msg.payload;
if (!p || !p.nodeId) { node.warn("paquet ignoré : nodeId absent"); return null; }
const faults = [];

if (checksum(p) !== p.checksum) faults.push("checksum_invalide");
for (const [k, [lo, hi]] of Object.entries(LIMITS)) {
    const v = p[k];
    if (typeof v !== "number" || Number.isNaN(v)) faults.push(k + "_absent");
    else if (k === "soil_moisture_pct" && v <= lo) faults.push("sonde_sol_deconnectee");   // lecture ≈ 0 : sonde débranchée
    else if (v < lo || v > hi) faults.push(k + "_hors_plage");
}
// séquence (paquets perdus / dupliqués) et sonde figée
const last = context.get("last_" + p.nodeId) || { seq: 0, sm: null, same: 0 };
if (last.seq > 0 && p.seq <= last.seq) faults.push("sequence_dupliquee");
else if (last.seq > 0 && p.seq > last.seq + 1) faults.push("paquets_perdus_" + (p.seq - last.seq - 1));
last.same = (last.sm === p.soil_moisture_pct) ? last.same + 1 : 0;
if (last.same >= 8) faults.push("sonde_sol_figee");
if (p.battery_pct < 15) faults.push("batterie_faible");
if (p.rssi_dbm < -105) faults.push("signal_faible");
context.set("last_" + p.nodeId, { seq: p.seq, sm: p.soil_moisture_pct, same: last.same });

p.gateway     = GATEWAY;
p.received_at = new Date().toISOString();
p.health      = { ok: faults.length === 0, faults };
msg.payload   = p;

node.status({ fill: faults.length ? "yellow" : "green", shape: "dot", text: `${p.nodeId} ${faults.length ? "⚠ " + faults[0] : "OK"}` });
const fault = faults.length
    ? { topic: `farm/${p.orchardId}/${p.nodeId}/health`, payload: { nodeId: p.nodeId, zone: p.zone, trees: p.trees, timestamp: p.timestamp, faults } }
    : null;
return [msg, fault];

// ============================================================
//  MÉMOIRE NUMÉRIQUE DU NŒUD (ZONE) · INDICES DE STRESS · LOGIQUE D'ALERTE
//  Les alertes parlent de la ZONE (nœud), pas d'un arbre.
//  Règles déterministes (modèle « rules-v1 ») — point d'accroche du service IA (§12)
// ============================================================
const MEMORY_SIZE  = 288;          // 3 jours simulés à 15 min
const TICK_MINUTES = 15;
const FIELD_CAP = 38, WILTING = 15, T_HEAT = 35;

const p    = msg.payload;
const mem  = flow.get("memoire") || {};
const tree = mem[p.nodeId] || { history: [], prevSeverity: "OK", persist: 0, faultHold: 0, lower: 0 };
const RANK = { CRITICAL: 4, WARNING: 3, WATCH: 2, INFO: 1, CAPTEUR: 1, OK: 0 };
const faults = p.health.faults;
const soilOk = !faults.some(f => f.startsWith("soil_moisture") || f.startsWith("sonde_sol") || f === "checksum_invalide");

// ---------- mémoire longitudinale (mesures valides seulement) ----------
const now = Date.parse(p.timestamp);
if (soilOk) tree.history.push({ t: now, sm: p.soil_moisture_pct, ta: p.air_temp_c, rh: p.humidity_pct, par: p.light_par });
if (tree.history.length > MEMORY_SIZE) tree.history.splice(0, tree.history.length - MEMORY_SIZE);
const H = tree.history;

// ---------- baseline personnalisée : plage « normale » apprise sur le premier jour de CE nœud ----------
const mean = a => a.reduce((x, y) => x + y, 0) / a.length;
const std  = a => { const m = mean(a); return Math.sqrt(mean(a.map(v => (v - m) ** 2))); };
let baseline = null;
if (H.length >= 24) {                                                       // ≥ 6 h de mesures valides
    const sms = H.slice(0, 96).map(x => x.sm);                              // 96 échantillons = 1 jour simulé
    baseline = { sm_mean: Math.round(mean(sms) * 10) / 10, sm_std: Math.max(2, std(sms)), n: sms.length };
}
// hystérésis des défauts capteur : un défaut maintient l'état CAPTEUR pendant 8 cycles (2 h simulées)
tree.faultHold = soilOk ? Math.max(0, tree.faultHold - 1) : 8;
const sensorFault = tree.faultHold > 0;

// ---------- features ----------
const clamp = (v, lo = 0, hi = 1) => Math.min(hi, Math.max(lo, v));
const ago6 = H.filter(x => x.t <= now - 6 * 3600000).pop();                 // mesure ≈ 6 h plus tôt
const dryingRate = (ago6 && soilOk) ? Math.max(0, (ago6.sm - p.soil_moisture_pct) / ((now - ago6.t) / 3600000)) : 0; // %/h
const hoursHot = H.filter(x => x.t > now - 24 * 3600000 && x.ta >= T_HEAT).length * TICK_MINUTES / 60;

// ---------- indices (0–100) ----------
let wsi = null, anomaly = null;
if (soilOk) {
    const deficit = clamp((FIELD_CAP - p.soil_moisture_pct) / (FIELD_CAP - WILTING));
    wsi = Math.round(100 * (0.60 * deficit + 0.25 * clamp(dryingRate / 1.5) + 0.15 * clamp(p.vpd_kpa / 3)));
}
const hsi = Math.round(100 * (0.50 * clamp((p.air_temp_c - 32) / 12) + 0.35 * clamp(hoursHot / 10) + 0.15 * clamp(p.light_par / 1800)));
if (baseline && soilOk) {
    const z = (baseline.sm_mean - p.soil_moisture_pct) / baseline.sm_std;    // > 0 : plus sec que d'habitude
    anomaly = Math.round(100 * clamp(z / 4)) / 100;
}

// ---------- logique d'alerte (§14) ----------
const zl = "zone " + p.zone;                    // ex. « zone 2 »
const nb = (p.tree_count || 0) + " arbres";
const signals = [];
if (wsi !== null && wsi >= 60) signals.push("stress hydrique");
if (hsi >= 60) signals.push("stress thermique");
if (anomaly !== null && anomaly >= 0.6) signals.push("écart au profil habituel");
const modere = (wsi !== null && wsi >= 40) || hsi >= 40 || (anomaly !== null && anomaly >= 0.6);
tree.persist = modere ? tree.persist + 1 : 0;
const hydrique = (wsi !== null && wsi >= hsi);

let severity = "OK", message = "", action = "";
if (sensorFault) {
    severity = "CAPTEUR";
    message  = `Zone ${p.zone} · nœud ${p.nodeId} : défaut capteur${faults.length ? " (" + faults.join(", ") + ")" : " récent"}. Indices de stress hydrique suspendus.`;
    action   = "Vérifier la sonde de sol et le câblage du nœud.";
} else if ((wsi !== null && wsi >= 80) || hsi >= 80 || p.soil_moisture_pct <= WILTING) {
    severity = "CRITICAL";
    message  = `Inspection immédiate recommandée : stress sévère détecté dans la ${zl} (${nb}).`;
    action   = hydrique ? "Irriguer sans délai et inspecter la zone racinaire." : "Protéger les arbres de la zone (ombrage, irrigation de rafraîchissement).";
} else if (signals.length >= 2) {
    severity = "WARNING";
    message  = hydrique
        ? `Le risque de stress hydrique augmente dans la ${zl}. Inspecter la ligne d'irrigation de la zone.`
        : `Le risque de stress thermique augmente dans la ${zl} (${nb}).`;
    action   = hydrique ? "Contrôler la ligne d'irrigation et l'humidité du sol." : "Prévoir un arrosage de rafraîchissement.";
} else if (modere && tree.persist >= 4) {
    severity = "WATCH";
    message  = hydrique
        ? `Stress hydrique possible dans la ${zl}. Vérifier l'irrigation et l'humidité du sol.`
        : `Exposition thermique prolongée dans la ${zl}. Surveiller l'évolution.`;
    action   = "Vérifier sur place dans la journée.";
} else if (anomaly !== null && anomaly >= 0.5) {
    severity = "INFO";
    message  = `La ${zl} sèche plus vite que d'habitude (profil habituel du nœud).`;
    action   = "Aucune action immédiate ; suivre la tendance.";
}
// hystérésis : on ne redescend d'un niveau qu'après 4 cycles consécutifs (1 h simulée) sous ce niveau
if (severity !== "CAPTEUR" && tree.prevSeverity !== "CAPTEUR" && RANK[severity] < RANK[tree.prevSeverity]) {
    tree.lower += 1;
    if (tree.lower < 4) severity = tree.prevSeverity;
} else tree.lower = 0;
const confidence = sensorFault ? 0.9 : Math.min(0.95, 0.45 + 0.15 * signals.length + (baseline ? 0.15 : 0) + Math.min(0.2, tree.persist * 0.02));

// ---------- codes (Supabase, applis LOOZ) : jamais de phrases ----------
// reasons = ce qui explique le niveau ; cause = water | heat | sensor (null si OK)
const reasons = [];
if (severity === "CAPTEUR") reasons.push("sensor_fault");
else if (severity !== "OK") {
    if (soilOk && p.soil_moisture_pct <= WILTING) reasons.push("wilting_point");
    if (wsi !== null && wsi >= 40) reasons.push("water_stress");
    if (hsi >= 40) reasons.push("heat_stress");
    if (anomaly !== null && anomaly >= 0.5) reasons.push("unusual_drying");
}
const cause = severity === "OK" ? null
            : severity === "CAPTEUR" ? "sensor"
            : (severity === "INFO" || hydrique) ? "water" : "heat";

p.indicators = { water_stress: wsi, heat_stress: hsi, anomaly_score: anomaly,
                 drying_rate_pct_h: Math.round(dryingRate * 100) / 100, hours_above_35c: Math.round(hoursHot * 10) / 10 };
p.baseline = baseline;
p.alert    = { severity, message, action, confidence: Math.round(confidence * 100) / 100, model: "rules-v1",
               reasons, cause };
msg.payload = p;

// événement d'alerte uniquement sur changement de niveau (alertes événementielles, pas de flux continu)
let event = null;
if (severity !== tree.prevSeverity) {
    const retour = severity === "OK";
    event = { topic: `farm/${p.orchardId}/alerts`, payload: {
        id: `${p.nodeId}-${p.seq}`, nodeId: p.nodeId, zone: p.zone, cultivar: p.cultivar,
        trees: p.trees, tree_count: p.tree_count,
        severity, previous: tree.prevSeverity,
        message: retour ? `Retour à la normale dans la ${zl}.` : message,
        action:  retour ? "Aucune." : action,
        confidence: p.alert.confidence, confidence_pct: Math.round(p.alert.confidence * 100),
        indicators: p.indicators, model: "rules-v1",
        timestamp: p.timestamp, timestamp_label: msg.simTime || p.timestamp
    } };
    tree.prevSeverity = severity;
}
mem[p.nodeId] = tree;
flow.set("memoire", mem);
node.status({ fill: severity === "OK" ? "green" : (severity === "CRITICAL" ? "red" : "yellow"), shape: "dot", text: `${p.nodeId} ${severity}` });
return [msg, event];

// ============================================================
//  JOURNAL DES ALERTES — conserve les 12 derniers événements
// ============================================================
const a = msg.payload;
const log = flow.get("journal_alertes") || [];
log.unshift(a);
if (log.length > 12) log.length = 12;
flow.set("journal_alertes", log);

const ICON = { CRITICAL: "🔴", WARNING: "🟠", WATCH: "🟡", INFO: "🔵", CAPTEUR: "⚙️", OK: "🟢" };
const notif = (a.severity === "WARNING" || a.severity === "CRITICAL")
    ? { payload: `${ICON[a.severity]} ${a.severity} · zone ${a.zone} (${a.nodeId}) — ${a.message}` }
    : null;
return [{ payload: log }, notif, { topic: msg.topic, payload: a }];

// ============================================================
//  DISPATCH DASHBOARD — 13 sorties (tableau, graphiques, KPI, nœud sélectionné)
// ============================================================
const p = msg.payload;
const latest = flow.get("latest") || {};
latest[p.nodeId] = p;
flow.set("latest", latest);
const sel  = flow.get("noeud_selectionne");
const RANK = { CRITICAL: 4, WARNING: 3, WATCH: 2, INFO: 1, CAPTEUR: 1, OK: 0 };
const ind  = p.indicators;
const out  = new Array(13).fill(null);

if (ind.water_stress !== null) out[1] = { topic: "Zone " + p.zone, payload: ind.water_stress };
out[2] = { topic: "Zone " + p.zone, payload: ind.heat_stress };
if (p.health.ok) out[3] = { topic: "Zone " + p.zone, payload: p.soil_moisture_pct };
out[4] = { topic: "Zone " + p.zone, payload: p.air_temp_c };

if (msg.lastOfTick) {
    const vals = Object.values(latest).sort((a, b) => a.nodeId.localeCompare(b.nodeId));
    out[0] = { payload: vals.map(r => ({
        "Zone": r.zone, "Nœud": r.nodeId, "Arbres": r.tree_count + " (" + (r.trees || []).join(", ") + ")", "Cultivar": r.cultivar,
        "Sol %": r.health.ok ? r.soil_moisture_pct : "⚠ " + r.soil_moisture_pct,
        "Air °C": r.air_temp_c, "HR %": r.humidity_pct, "PAR": r.light_par,
        "Stress hydrique": r.indicators.water_stress === null ? "—" : r.indicators.water_stress,
        "Stress thermique": r.indicators.heat_stress,
        "Anomalie": r.indicators.anomaly_score === null ? "—" : r.indicators.anomaly_score,
        "Niveau": r.alert.severity, "Batterie %": r.battery_pct, "RSSI dBm": r.rssi_dbm
    })) };
    out[5] = { payload: `${vals.filter(v => v.health.ok).length} sains / ${vals.length} nœuds en ligne · ${vals.reduce((n, v) => n + (v.tree_count || 0), 0)} arbres suivis` };
    out[6] = { payload: String(vals.filter(v => RANK[v.alert.severity] >= 2).length) };
    out[7] = { payload: msg.simTime || p.timestamp };
}

if (p.nodeId === sel) {
    if (p.health.ok) out[8] = { payload: p.soil_moisture_pct };
    out[9]  = { payload: p.air_temp_c };
    if (ind.water_stress !== null) out[10] = { payload: ind.water_stress };
    out[11] = { payload: ind.heat_stress };
    out[12] = { payload: p };
}
return out;

// ============================================================
//  CODES POUR SUPABASE (LOOZ)
//  Chaque mesure notée devient une ligne de CODES (aucune phrase : chaque
//  appli écrit ses textes dans sa langue). Les lignes attendent dans la
//  mémoire du flux (supabase_buffer, gardée sur le disque) ; le nœud
//  « Lot Supabase » les envoie une fois par minute.
// ============================================================
const MAX_BUFFER = 5000;   // ≈ 100 min de mesures si Supabase ne répond pas
const LEVEL = { OK: "ok", INFO: "info", WATCH: "watch", WARNING: "warning", CRITICAL: "critical", CAPTEUR: "sensor" };
const FIELD = { soil_moisture_pct: "soil_moisture", soil_temp_c: "soil_temp", air_temp_c: "air_temp",
                humidity_pct: "humidity", light_par: "light", battery_pct: "battery" };

// Codes de la passerelle (français) -> codes LOOZ (migration 012).
function faultCode(f) {
    if (f === "checksum_invalide") return "checksum_invalid";
    if (f === "sonde_sol_deconnectee") return "soil_probe_disconnected";
    if (f === "sonde_sol_figee") return "soil_probe_stuck";
    if (f === "sequence_dupliquee") return "duplicate_seq";
    if (f.startsWith("paquets_perdus_")) return "packets_lost";
    if (f === "batterie_faible") return "battery_low";
    if (f === "signal_faible") return "signal_weak";
    for (const [k, short] of Object.entries(FIELD)) {
        if (f === k + "_hors_plage") return short + "_out_of_range";
        if (f === k + "_absent") return short + "_missing";
    }
    return "other";
}
const num = v => (typeof v === "number" && Number.isFinite(v)) ? v : null;

const p = msg.payload;
const faults = (p.health && p.health.faults) || [];
let packetsLost = 0;
for (const f of faults) if (f.startsWith("paquets_perdus_")) packetsLost += Number(f.slice(15)) || 0;

// Mode démo : l'horloge simulée est l'heure de TUNISIE écrite comme UTC
// (« 05:00Z » = 05:00 à Sfax) -> on enlève 1 h pour envoyer le vrai instant.
const demo = (env.get("LOOZ_TIME_MODE") || "demo") === "demo";
const t = Date.parse(p.timestamp) - (demo ? 3600000 : 0);
if (!Number.isFinite(t)) { node.warn("mesure sans heure : ignorée"); return null; }
const ind = p.indicators || {};
const a = p.alert || {};

const reading = {
    device: p.nodeId,
    measured_at: new Date(t).toISOString(),
    seq: num(p.seq),
    soil_moisture_pct: num(p.soil_moisture_pct),
    soil_temp_c: num(p.soil_temp_c),
    air_temp_c: num(p.air_temp_c),
    humidity_pct: num(p.humidity_pct),
    light_par: num(p.light_par),
    vpd_kpa: num(p.vpd_kpa),
    battery_pct: num(p.battery_pct),
    rssi_dbm: num(p.rssi_dbm),
    water_stress: num(ind.water_stress),
    heat_stress: num(ind.heat_stress),
    anomaly: num(ind.anomaly_score),
    drying_rate_pct_h: num(ind.drying_rate_pct_h),
    hours_above_35c: num(ind.hours_above_35c),
    packets_lost: packetsLost,
    level: LEVEL[a.severity] || null,
    reasons: Array.isArray(a.reasons) ? a.reasons : [],
    cause: a.cause || null,
    confidence: num(a.confidence),
    faults: [...new Set(faults.map(faultCode))],
    firmware: p.firmware || null,
    model: a.model || null
};

const buffer = flow.get("supabase_buffer") || [];
buffer.push(reading);
// Trop de mesures en attente (Supabase injoignable) : les plus vieilles partent,
// mais jamais pendant un envoi (le lot en cours garde sa place).
if (buffer.length > MAX_BUFFER && !flow.get("supabase_inflight")) buffer.splice(0, buffer.length - MAX_BUFFER);
flow.set("supabase_buffer", buffer);
node.status({ fill: "grey", shape: "dot", text: `${buffer.length} mesure(s) en attente` });
return null;

// ============================================================
//  LOT SUPABASE (LOOZ) — toutes les 10 s : est-ce l'heure d'envoyer ?
//  Un lot = les mesures en attente (500 au plus) -> Edge Function
//  iot-ingest. Réglages dans iot/node-red/.env (jamais dans ce fichier) :
//    LOOZ_INGEST_URL, LOOZ_GATEWAY_KEY (secret), LOOZ_GATEWAY_CODE,
//    LOOZ_BATCH_SECONDS (60 ; 20 pour une démo devant un jury).
// ============================================================
const MAX_PER_BATCH = 500;
const url = env.get("LOOZ_INGEST_URL") || "";
const key = env.get("LOOZ_GATEWAY_KEY") || "";
const gateway = env.get("LOOZ_GATEWAY_CODE") || "GW-01";
const every = Math.max(10, Number(env.get("LOOZ_BATCH_SECONDS")) || 60) * 1000;

const buffer = flow.get("supabase_buffer") || [];
if (!/^https:\/\/|^http:\/\/(127\.0\.0\.1|localhost)[:/]/.test(url) || !/^lgw_[0-9a-f]{64}$/.test(key)) {
    node.status({ fill: "red", shape: "ring", text: `URL ou clé absente de .env · ${buffer.length} en attente` });
    return null;
}
const inflight = flow.get("supabase_inflight");
if (inflight && Date.now() - inflight.at < 60000) return null;      // le lot précédent n'a pas encore répondu
const last = context.get("last_send") || 0;
// Du retard (plus d'un lot en attente) : on rattrape toutes les 10 s.
const wait = buffer.length > MAX_PER_BATCH ? 10000 : every;
if (Date.now() - last < wait - 500) return null;
if (!buffer.length) {
    node.status({ fill: "grey", shape: "ring", text: "rien à envoyer" });
    return null;
}
context.set("last_send", Date.now());
const readings = buffer.slice(0, MAX_PER_BATCH);
flow.set("supabase_inflight", { count: readings.length, at: Date.now() });
node.status({ fill: "blue", shape: "dot", text: `envoi de ${readings.length} mesures…` });
return {
    url,
    method: "POST",
    requestTimeout: 30000,
    headers: { "content-type": "application/json", "x-looz-gateway-key": key },
    payload: { gateway, sent_at: new Date().toISOString(), readings }
};

// ============================================================
//  RÉPONSE SUPABASE (LOOZ)
//  200 : le lot est enregistré -> il quitte la mémoire.
//  Autre : les mesures restent et repartent au lot suivant.
// ============================================================
const inflight = flow.get("supabase_inflight") || { count: 0 };
flow.set("supabase_inflight", null);
delete msg.headers;                          // la clé ne va nulle part ailleurs
const code = msg.statusCode;
const p2 = v => String(v).padStart(2, "0");
const d = new Date();
const at = `${p2(d.getHours())}:${p2(d.getMinutes())}:${p2(d.getSeconds())}`;
const buffer = flow.get("supabase_buffer") || [];

if (code === 200 && msg.payload && typeof msg.payload === "object") {
    buffer.splice(0, inflight.count);
    flow.set("supabase_buffer", buffer);
    const r = msg.payload;
    const refused = Object.entries(r.refused || {}).map(([k, n]) => `${n} ${k}`).join(", ");
    const text = `✓ ${at} · ${r.accepted} acceptée(s)` + (r.old ? ` · ${r.old} déjà reçue(s)` : "")
               + (refused ? ` · refusées : ${refused}` : "") + (buffer.length ? ` · ${buffer.length} en attente` : "");
    node.status({ fill: refused ? "yellow" : "green", shape: "dot", text });
    if (refused) node.warn(`Supabase a refusé : ${refused} ${JSON.stringify(r.refused_devices || {})}`);
    return { payload: `${text}` };
}
const why = code === 401 ? "clé refusée (401) : vérifiez LOOZ_GATEWAY_KEY"
          : code === 503 ? "réception coupée dans Supabase (503)"
          : code === 404 ? "fonction iot-ingest introuvable (404)"
          : code === 400 ? "lot refusé (400)"
          : code === 413 ? "lot trop gros (413)"
          : `pas de réponse (${code || "réseau"})`;
const text = `✗ ${at} · ${why} · ${buffer.length} en attente`;
node.status({ fill: "red", shape: "ring", text });
node.warn(`Envoi à Supabase échoué : ${why}`);
return { payload: text };
